create table public.student_documents(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,category text not null check(category in('photo','birth_certificate','previous_school','aadhaar','medical','other')),title text not null,storage_path text not null,mime_type text,size_bytes bigint,uploaded_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(school_id,storage_path));
create index student_documents_student_idx on public.student_documents(student_id,created_at desc);
alter table public.student_documents enable row level security;
create policy "view student documents" on public.student_documents for select to authenticated using(public.can_view_student(student_id));
create policy "manage student documents" on public.student_documents for all to authenticated using(public.has_school_role(school_id,array['school_owner','principal','reception']::public.school_role[])) with check(public.has_school_role(school_id,array['school_owner','principal','reception']::public.school_role[]));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('student-documents','student-documents',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "school document read" on storage.objects for select to authenticated using(bucket_id='student-documents' and exists(select 1 from public.student_documents d where d.storage_path=name and public.can_view_student(d.student_id)));
create policy "school document insert" on storage.objects for insert to authenticated with check(bucket_id='student-documents' and public.has_school_role(((storage.foldername(name))[1])::uuid,array['school_owner','principal','reception']::public.school_role[]));
create policy "school document delete" on storage.objects for delete to authenticated using(bucket_id='student-documents' and public.has_school_role(((storage.foldername(name))[1])::uuid,array['school_owner','principal','reception']::public.school_role[]));